/**
 * n8n Code node — inside a SplitInBatches loop, batch size 1.
 *
 *   Ticker Extraction -> New Fundamentals Loop (size 1) -> HTTP Request
 *     -> THIS NODE -> Switch on `target` -> 4 Postgres nodes -> back to loop
 *
 * Emits FIVE row shapes, keyed by `target`:
 *   'company'  -> one row  (General:: fields, fiscal calendar)
 *   'quality'  -> 0-n rows (data defects found in THIS payload)
 *   'fact'     -> quarterly/yearly statement facts
 *   'market_stats' -> one wide row (beta, share counts, short interest,
 *                     ownership %, analyst target) - the fields that are NOT
 *                     derivable from the statements and are currency-safe.
 *                     Everything else the old snapshot carried (revenue, EBITDA,
 *                     per-share values, valuation ratios) is now derived in USD
 *                     by the fundamentals_snapshot view and is dropped here.
 *   'earnings' -> 0-n rows (EPS actual/estimate/surprise per quarter — the
 *                 only source of analyst estimates; not derivable from statements)
 *
 * General:: fields are read generically, so Sector/Industry/GicSector/etc.
 * are picked up without code changes as EODHD adds them.
 *
 * FiscalYearEnd arrives as a month NAME. A month is not a date, so three
 * fields are emitted: month number, last calendar day (leap-aware), and an
 * ISO date anchored to the most recent FY end on or before the latest quarter.
 *
 * Values are NOT sign-normalised. capitalExpenditures is POSITIVE in EODHD and
 * freeCashFlow is pre-computed. Fix signs downstream, deliberately, once.
 */

// ---------------------------------------------------------------- config ----

const SOURCE = 'eodhd';
const LOOP_NODE = 'New Fundamentals Loop';

// Optional Set node BEFORE the loop stamping as_of = {{ $now.toISO() }} so
// every ticker in one sweep shares a timestamp. null = per-iteration now().
const RUN_STAMP_NODE = null;
const RUN_STAMP_FIELD = 'as_of';

const TICKER_FIELDS = ['ticker', 'Ticker', 'symbol', 'Symbol', 'code', 'Code'];

const EXCHANGE_SUFFIXES = new Set([
  'US', 'LSE', 'TO', 'V', 'AS', 'PA', 'F', 'XETRA', 'MI', 'MC', 'ST',
  'HE', 'CO', 'OL', 'SW', 'VI', 'IR', 'BR', 'LS', 'AU', 'HK', 'TSE',
]);

const EMIT_SUMMARY = false;   // debug only; Postgres nodes expect real rows

const PERIODIC_KEY = /^Financials::([A-Za-z_]+)::(quarterly|yearly)$/;
const GENERAL_FLAT = /^General::(.+)$/;

const METADATA_KEYS = new Set(['date', 'filing_date', 'currency_symbol']);

const ATTRIBUTE_OVERRIDES = {
  '52WeekHigh': 'week_52_high',
  '52WeekLow': 'week_52_low',
  '50DayMA': 'ma_50',
  '200DayMA': 'ma_200',
  nonCurrrentAssetsOther: 'non_current_assets_other', // sic: EODHD triple-r
  capitalSurpluse: 'capital_surplus',                 // sic: EODHD typo
  totalLiab: 'total_liabilities',
  deferredLongTermLiab: 'deferred_long_term_liabilities',
  otherLiab: 'other_liabilities',
  otherCurrentLiab: 'other_current_liabilities',
};

// General:: -> company row columns. Add a line when EODHD adds a field.
const COMPANY_FIELDS = {
  Name: 'name',
  Exchange: 'exchange',
  CurrencyCode: 'currency',
  CountryISO: 'country',
  Sector: 'sector',
  Industry: 'industry',
  GicSector: 'gic_sector',
  GicGroup: 'gic_group',
  GicIndustry: 'gic_industry',
  GicSubIndustry: 'gic_sub_industry',
  IPODate: 'ipo_date',
  Type: 'security_type',
  ISIN: 'isin',
  CIK: 'cik',
  IsDelisted: 'is_delisted',
};

// -- Quality thresholds ------------------------------------------------------
const Q = {
  eps_divergence_pct: 25,       // vendor EPS vs EPS computed from statements
  shares_jump_pct: 20,          // QoQ share-count discontinuity
  identity_gap_pct: 0.5,        // assets vs liabilities + equity
  cf_ni_divergence_pct: 10,     // cash-flow netIncome vs income-statement
  filing_lag_min_days: 1,       // filing_date must postdate period_end
  filing_lag_share: 0.5,        // share of periods with no lag before flagging

  // preliminary-period detection
  round_unit: 1000000,          // exact multiples of $1m
  round_min_values: 15,         // need this many values to judge a period
  round_share_pct: 40,          // >this share of round values = preliminary
  round_min_abs: 1000000,       // ignore small values; they round trivially

  // component reclassification (same money moved between line items)
  component_swing_pct: 50,      // component moved this much QoQ...
  total_stable_pct: 15,         // ...while its total moved less than this

  repeated_min_abs: 1000000,    // identical consecutive values above this
};

// repeated_value applies to FLOW statements only. Balance-sheet items are
// stocks: an unchanged share count or capital stock across quarters is a real
// company that issued nothing, not a carry-forward. Flagging those buries the
// genuine hits in noise.
const FLOW_STATEMENTS = new Set(['income_statement', 'cash_flow']);

// Components that must sum consistently to a stable total.
const COMPONENT_TOTALS = [
  {
    total: 'short_long_term_debt_total',
    // short_term_debt is deliberately NOT a part: long-term debt moving into
    // current as it approaches maturity is real accounting, not vendor
    // reclassification. Including it fires on healthy issuers.
    parts: ['long_term_debt', 'capital_lease_obligations'],
    label: 'debt',
  },
];

const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;

const MONTHS = {
  january: 1, jan: 1, february: 2, feb: 2, march: 3, mar: 3, april: 4, apr: 4,
  may: 5, june: 6, jun: 6, july: 7, jul: 7, august: 8, aug: 8,
  september: 9, sep: 9, sept: 9, october: 10, oct: 10,
  november: 11, nov: 11, december: 12, dec: 12,
};

// ------------------------------------------------------------- utilities ----

function toSnake(key) {
  if (ATTRIBUTE_OVERRIDES[key]) return ATTRIBUTE_OVERRIDES[key];
  return key
    .replace(/([a-z0-9])([A-Z])/g, '$1_$2')
    .replace(/([A-Z]+)([A-Z][a-z])/g, '$1_$2')
    .replace(/[^A-Za-z0-9]+/g, '_')
    .replace(/_+/g, '_')
    .replace(/^_|_$/g, '')
    .toLowerCase();
}

function coerceValue(raw) {
  if (raw === null || raw === undefined) return null;
  if (typeof raw === 'boolean') return { num: raw ? 1 : 0 };
  if (typeof raw === 'number') return Number.isFinite(raw) ? { num: raw } : null;

  if (typeof raw === 'string') {
    const s = raw.trim();
    if (s === '' || s === 'NA' || s === 'N/A' || s === '-' || s === 'null') return null;
    if (ISO_DATE.test(s)) return { text: s };
    const cleaned = s.replace(/,/g, '');
    if (/^-?\d+(\.\d+)?([eE][-+]?\d+)?$/.test(cleaned)) {
      const n = Number(cleaned);
      if (Number.isFinite(n)) return { num: n };
    }
    return { text: s };
  }
  return null;
}

function normaliseDate(raw) {
  if (typeof raw !== 'string') return null;
  const s = raw.trim();
  if (!ISO_DATE.test(s)) return null;
  if (s.startsWith('0000')) return null;   // EODHD placeholder
  return s;
}

function normaliseTicker(raw) {
  if (raw === null || raw === undefined) return null;
  let t = String(raw).trim().toUpperCase();
  if (!t) return null;
  const dot = t.lastIndexOf('.');
  if (dot > 0 && EXCHANGE_SUFFIXES.has(t.slice(dot + 1))) t = t.slice(0, dot);
  return t || null;
}

// Sentinel strings EODHD uses instead of null. 'NA' lands in the DB as the
// literal two-character string unless caught here.
const NULL_SENTINELS = new Set(['', 'NA', 'N/A', 'N.A.', '-', '--', 'null', 'NULL', 'None', '0000-00-00']);

// Reverse map for CP1252 0x80-0x9F, which Latin-1 leaves undefined. Without
// this the smart-quote family (' " - --) cannot be round-tripped.
const CP1252_HIGH = {
  0x20AC: 0x80, 0x201A: 0x82, 0x0192: 0x83, 0x201E: 0x84, 0x2026: 0x85,
  0x2020: 0x86, 0x2021: 0x87, 0x02C6: 0x88, 0x2030: 0x89, 0x0160: 0x8A,
  0x2039: 0x8B, 0x0152: 0x8C, 0x017D: 0x8E, 0x2018: 0x91, 0x2019: 0x92,
  0x201C: 0x93, 0x201D: 0x94, 0x2022: 0x95, 0x2013: 0x96, 0x2014: 0x97,
  0x02DC: 0x98, 0x2122: 0x99, 0x0161: 0x9A, 0x203A: 0x9B, 0x0153: 0x9C,
  0x017E: 0x9E, 0x0178: 0x9F,
};

/**
 * Repair UTF-8 bytes that were decoded as CP1252 ('AeromÃ©xico' -> 'Aeroméxico').
 * The damage arrives already present in the HTTP response, so fixing it here
 * stops it reaching the database rather than repairing rows after the fact.
 * Returns the input unchanged unless the reinterpretation yields valid UTF-8,
 * so clean names (Ørsted, Ålandsbanken, Nestlé) pass through untouched.
 */
function fixMojibake(s) {
  if (typeof s !== 'string' || !s) return s;
  if (!/[\u00C2\u00C3\u00E2\u00C5\u00D0\u00D1]/.test(s)) return s;
  const bytes = [];
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (cp <= 0xFF) bytes.push(cp);
    else if (CP1252_HIGH[cp] !== undefined) bytes.push(CP1252_HIGH[cp]);
    else return s;                       // not representable: not mojibake
  }
  try {
    const decoded = Buffer.from(bytes).toString('utf8');
    if (decoded.indexOf('\uFFFD') !== -1) return s;   // invalid UTF-8
    return decoded;
  } catch (e) {
    return s;
  }
}

/** Trim, null out sentinels, repair encoding. For company-row string fields. */
function cleanCompanyString(v) {
  if (v === null || v === undefined) return null;
  if (typeof v !== 'string') return v;
  const t = v.trim();
  if (NULL_SENTINELS.has(t)) return null;
  return fixMojibake(t);
}

function pickTickerField(json) {
  if (!json || typeof json !== 'object') return null;
  for (const f of TICKER_FIELDS) {
    if (json[f] !== undefined && json[f] !== null && json[f] !== '') return json[f];
  }
  return null;
}

function daysBetween(aIso, bIso) {
  return Math.round((Date.parse(aIso) - Date.parse(bIso)) / 86400000);
}

function pctDiff(a, b) {
  if (a === null || b === null || !Number.isFinite(a) || !Number.isFinite(b)) return null;
  if (Math.abs(b) === 0) return null;
  return 100 * (a - b) / Math.abs(b);
}

function round4(n) {
  return (n === null || n === undefined || !Number.isFinite(n)) ? null : Number(n.toFixed(4));
}

// -------------------------------------------------- fiscal year end -------

function lastDayOfMonth(y, m) {
  return new Date(Date.UTC(y, m, 0)).getUTCDate();   // leap-aware
}

function parseFiscalMonth(raw) {
  if (raw === null || raw === undefined) return null;
  const s = String(raw).trim().toLowerCase();
  if (!s) return null;

  const word = s.split(/[\s,\-\/]+/)[0];
  if (MONTHS[word]) return MONTHS[word];

  const iso = normaliseDate(s);
  if (iso) return Number(iso.slice(5, 7));
  const n = Number(word);
  if (Number.isInteger(n) && n >= 1 && n <= 12) return n;
  return null;
}

/** Most recent fiscal year end on or before anchorIso. */
function fiscalYearEndDate(month, anchorIso) {
  if (!month) return null;
  const anchor = anchorIso ? new Date(anchorIso + 'T00:00:00Z') : new Date();
  let y = anchor.getUTCFullYear();
  let d = lastDayOfMonth(y, month);
  if (Date.UTC(y, month - 1, d) > anchor.getTime()) {
    y -= 1;
    d = lastDayOfMonth(y, month);
  }
  return { iso: `${y}-${String(month).padStart(2, '0')}-${String(d).padStart(2, '0')}`, day: d };
}

// -------------------------------------------- run identity (as_of, run_id) ---

function resolveRunId() {
  try {
    if (typeof $execution !== 'undefined' && $execution && $execution.id) return String($execution.id);
  } catch (e) { /* older n8n */ }
  return null;
}

function resolveAsOf() {
  if (RUN_STAMP_NODE) {
    try {
      const stamp = $(RUN_STAMP_NODE).first().json[RUN_STAMP_FIELD];
      if (stamp) {
        const d = new Date(stamp);
        if (!isNaN(d.getTime())) return d.toISOString();
      }
    } catch (e) { /* fall through */ }
  }
  return new Date().toISOString();
}

const RUN_ID = resolveRunId();
const AS_OF = resolveAsOf();

// ------------------------------------------------- ticker resolution --------

/** SplitInBatches exposes the current batch on branch 1; .all() defaults to 0. */
function loopItems() {
  for (const args of [[1], [0], []]) {
    try {
      const r = $(LOOP_NODE).all(...args);
      if (Array.isArray(r) && r.length) return r;
    } catch (e) { /* next signature */ }
  }
  return null;
}

/** Read General:: from either the flattened or nested shape. */
function readGeneral(payload) {
  const g = {};
  if (payload.General && typeof payload.General === 'object') Object.assign(g, payload.General);
  for (const [k, v] of Object.entries(payload)) {
    const m = GENERAL_FLAT.exec(k);
    if (m) g[m[1]] = v;
  }
  return g;
}

function resolveTicker(general, payload, itemJson, loopList, payloadCount) {
  const selfDescribed =
    normaliseTicker(general.Code) ||
    normaliseTicker(pickTickerField(payload)) ||
    normaliseTicker(pickTickerField(itemJson));

  const fromLoop = loopList && loopList.length === 1
    ? normaliseTicker(pickTickerField(loopList[0].json)) : null;

  if (payloadCount !== 1) {
    throw new Error(
      `Expected exactly 1 fundamentals payload per loop iteration, got ${payloadCount}. ` +
      `Check ${LOOP_NODE} batch size is 1 and the HTTP node returns one response.`
    );
  }
  if (loopList && loopList.length > 1) {
    throw new Error(`${LOOP_NODE} returned ${loopList.length} items — batch size is not 1.`);
  }
  if (selfDescribed && fromLoop && selfDescribed !== fromLoop) {
    throw new Error(
      `Ticker mismatch: payload says "${selfDescribed}", ${LOOP_NODE} says "${fromLoop}". ` +
      `The HTTP response does not belong to the current loop item — stop, do not load.`
    );
  }
  const ticker = selfDescribed || fromLoop;
  if (!ticker) {
    throw new Error(
      `No ticker resolvable. Payload has no General::Code and $('${LOOP_NODE}') is ` +
      `unreachable or carries no ticker field (${TICKER_FIELDS.join(', ')}). ` +
      `Note: {{ }} syntax does not work inside a Code node.`
    );
  }
  return ticker;
}

// -------------------------------------------------------------- emitters ----

function makeRow(ctx, attributeKey, rawValue, out, stats, index) {
  if (METADATA_KEYS.has(attributeKey)) return;

  const coerced = coerceValue(rawValue);
  if (coerced === null) { stats.nullsDropped += 1; return; }

  const attribute = toSnake(attributeKey);
  if (!attribute) { stats.badAttributes.push(attributeKey); return; }

  const key = [ctx.statement, ctx.frequency, ctx.period_end, attribute].join('|');
  if (out.has(key)) stats.collisions.push(key);

  out.set(key, {
    target: 'fact',   // makeRow now serves statement facts only
    ticker: ctx.ticker,
    statement: ctx.statement,
    frequency: ctx.frequency,
    period_end: ctx.period_end,
    attribute,
    value_num: coerced.num !== undefined ? coerced.num : null,
    value_text: coerced.text !== undefined ? coerced.text : null,
    filing_date: ctx.filing_date,
    currency: ctx.currency,
    as_of: AS_OF,
    run_id: RUN_ID,
    source: SOURCE,
  });

  if (index && coerced.num !== undefined) {
    const st = index[ctx.statement] || (index[ctx.statement] = {});
    const pd = st[ctx.period_end] || (st[ctx.period_end] = {});
    pd[attribute] = coerced.num;
  }
}

function emitSection(sectionObj, ctx, out, stats, index) {
  for (const [k, v] of Object.entries(sectionObj)) {
    if (v !== null && typeof v === 'object') {
      for (const [k2, v2] of Object.entries(v)) makeRow(ctx, `${k}_${k2}`, v2, out, stats, index);
      continue;
    }
    makeRow(ctx, k, v, out, stats, index);
  }
}

// Market/ownership stats: one wide row per ticker for market_stats. Only the
// fields that cannot be reconstructed from the financial statements and are
// currency-safe - beta (unitless), the share/short counts, the ownership
// percentages, and WallStreetTargetPrice (quoted in the listing currency, USD).
// Short and beta appear in both SharesStats and Technicals; prefer SharesStats,
// fall back to Technicals.
function emitMarketStats(payload, ticker, out) {
  const tech = payload.Technicals  || {};
  const shr  = payload.SharesStats || {};
  const high = payload.Highlights  || {};
  const num = (raw) => {
    const c = coerceValue(raw);
    return c && c.num !== undefined ? c.num : null;
  };

  out.set(`market_stats|${ticker}`, {
    target: 'market_stats',
    ticker,
    beta:                     num(tech.Beta),
    shares_outstanding:       num(shr.SharesOutstanding),
    shares_float:             num(shr.SharesFloat),
    shares_short:             num(shr.SharesShort ?? tech.SharesShort),
    shares_short_prior_month: num(shr.SharesShortPriorMonth ?? tech.SharesShortPriorMonth),
    short_ratio:              num(shr.ShortRatio ?? tech.ShortRatio),
    short_percent_float:      num(shr.ShortPercentFloat ?? tech.ShortPercent),
    percent_insiders:         num(shr.PercentInsiders),
    percent_institutions:     num(shr.PercentInstitutions),
    wall_street_target:       num(high.WallStreetTargetPrice),
    as_of:                    AS_OF,
    run_id:                   RUN_ID,
    source:                   SOURCE,
  });
}

// Earnings history: one row per reported/scheduled quarter for earnings_calendar.
// This is the only source of analyst estimates and EPS surprise - none of it is
// derivable from the statements, and it is what the fundamentals scorer uses for
// the EPS magnitude gate, the acceleration score and the surprise score.
// Emitted as its own array rather than into `out`, because `out` is sorted by
// statement/period_end/attribute at the end and these rows carry none of those.
function emitEarnings(payload, ticker) {
  // Path-keyed filters return a flat "Earnings::History"; a plain `Earnings`
  // filter returns it nested. Accept either so the filter can change freely.
  const hist = payload['Earnings::History']
            || (payload.Earnings && payload.Earnings.History)
            || null;
  if (!hist || typeof hist !== 'object') return [];

  const num = (raw) => {
    const c = coerceValue(raw);
    return c && c.num !== undefined ? c.num : null;
  };

  const rows = [];
  for (const [key, e] of Object.entries(hist)) {
    if (!e || typeof e !== 'object') continue;
    const report_date = normaliseDate(e.reportDate);
    if (!report_date) continue;          // half the PK; the row cannot be upserted
    rows.push({
      target: 'earnings',
      ticker,
      report_date,
      period_end:          normaliseDate(e.date) || normaliseDate(key),
      before_after_market: e.beforeAfterMarket || null,
      currency:            e.currency || null,
      // null actual = scheduled but not yet reported. Kept deliberately: it is
      // real forward data, and the scorer already filters on epsActual !== null.
      actual:              num(e.epsActual),
      estimate:            num(e.epsEstimate),
      difference:          num(e.epsDifference),
      surprise_pct:        num(e.surprisePercent),
      as_of: AS_OF, run_id: RUN_ID, source: SOURCE,
    });
  }
  return rows.sort((a, b) => b.report_date.localeCompare(a.report_date));
}

// ------------------------------------------------------------------ main ----

function transform(payload, ticker, out, stats, index, filings) {
  emitMarketStats(payload, ticker, out);

  for (const [srcKey, periods] of Object.entries(payload)) {
    const m = PERIODIC_KEY.exec(srcKey);
    if (!m || !periods || typeof periods !== 'object') continue;

    const statement = toSnake(m[1]);
    const frequency = m[2];

    for (const [periodKey, period] of Object.entries(periods)) {
      if (!period || typeof period !== 'object') continue;

      const period_end = normaliseDate(period.date) || normaliseDate(periodKey);
      if (!period_end) { stats.badPeriods.push(`${statement}:${periodKey}`); continue; }

      const filing_date = normaliseDate(period.filing_date);
      if (frequency === 'quarterly') filings.push({ period_end, filing_date });

      emitSection(period, {
        ticker, statement, frequency, period_end, filing_date,
        currency: period.currency_symbol || null,
      }, out, stats, index);
    }
  }
}

// --------------------------------------------------------- quality checks ----

function allPeriods(index) {
  const s = new Set();
  for (const st of Object.values(index)) for (const p of Object.keys(st)) s.add(p);
  return [...s].sort();
}

function qualityFlags(ticker, payload, index, filings) {
  const flags = [];
  const add = (check, severity, value_num, period_end, detail) =>
    flags.push({
      target: 'quality', ticker, check, severity,
      value_num: round4(value_num), period_end: period_end || null,
      detail: detail || null, as_of: AS_OF, run_id: RUN_ID, source: SOURCE,
    });

  const bs = index.balance_sheet || {};
  const is_ = index.income_statement || {};
  const cf = index.cash_flow || {};
  const hl = (payload.Highlights && typeof payload.Highlights === 'object') ? payload.Highlights : {};

  const qPeriods = Object.keys(is_).sort().reverse();
  const bPeriods = Object.keys(bs).sort();
  const periods = allPeriods(index);

  // 1. filing_date carries no lag -> lookahead risk in point-in-time queries
  const q = filings.filter((f) => f.filing_date);
  if (q.length) {
    const noLag = q.filter((f) => daysBetween(f.filing_date, f.period_end) < Q.filing_lag_min_days);
    const share = noLag.length / q.length;
    if (share > Q.filing_lag_share) {
      add('filing_date_no_lag', 'high', 100 * share, null,
        `${noLag.length}/${q.length} periods have filing_date <= period_end; EODHD ` +
        `defaulted to period end. Apply a conservative lag in PIT queries.`);
    }
  }

  // 2. PRELIMINARY PERIOD: values rounded to the nearest million.
  //    Filed statements carry cents. A period where most large values are exact
  //    multiples of $1m was populated from a press release or an estimate, not
  //    a filing — exclude it from TTM until precise figures arrive.
  for (const p of periods) {
    let total = 0, round = 0;
    for (const st of Object.values(index)) {
      const row = st[p];
      if (!row) continue;
      for (const v of Object.values(row)) {
        if (typeof v !== 'number' || Math.abs(v) < Q.round_min_abs) continue;
        total += 1;
        if (v % Q.round_unit === 0) round += 1;
      }
    }
    if (total >= Q.round_min_values) {
      const share = 100 * round / total;
      if (share > Q.round_share_pct) {
        add('preliminary_period', 'high', share, p,
          `${round}/${total} values are exact multiples of ${Q.round_unit.toLocaleString()}. ` +
          `Filed statements carry cents — this period is preliminary/estimated. ` +
          `Exclude from TTM until precise figures land.`);
      }
    }
  }

  // 3. share-count discontinuity
  let prevShares = null, prevP = null;
  for (const p of bPeriods) {
    const s = bs[p] && bs[p].common_stock_shares_outstanding;
    if (s && prevShares) {
      const chg = pctDiff(s, prevShares);
      if (chg !== null && Math.abs(chg) > Q.shares_jump_pct) {
        add('shares_outstanding_jump', 'high', chg, p,
          `${prevP}: ${prevShares.toLocaleString()} -> ${p}: ${s.toLocaleString()}. ` +
          `Per-share metrics spanning this break are invalid.`);
      }
    }
    if (s) { prevShares = s; prevP = p; }
  }

  // 4. vendor EPS vs EPS computed from the statements
  const shares = bPeriods.length
    ? bs[bPeriods[bPeriods.length - 1]].common_stock_shares_outstanding : null;
  if (shares && qPeriods.length >= 4) {
    let ttm = 0, n = 0;
    for (const p of qPeriods.slice(0, 4)) {
      const ni = is_[p] && is_[p].net_income;
      if (typeof ni === 'number') { ttm += ni; n += 1; }
    }
    if (n === 4) {
      const computed = ttm / shares;
      for (const f of ['EarningsShare', 'DilutedEpsTTM']) {
        const vendor = hl[f];
        if (typeof vendor === 'number' && vendor !== 0 && computed !== 0) {
          const div = pctDiff(vendor, computed);
          if (div !== null && Math.abs(div) > Q.eps_divergence_pct) {
            add('vendor_eps_divergence', 'high', div, qPeriods[0],
              `${f}=${vendor} vs computed TTM EPS=${computed.toFixed(4)} ` +
              `(TTM NI ${Math.round(ttm).toLocaleString()} / ${shares.toLocaleString()} shares). ` +
              `Vendor PERatio and anything built on it are unusable for this ticker.`);
          }
        }
      }
    }
  }

  // 5. accounting identity
  for (const p of bPeriods.slice().reverse().slice(0, 4)) {
    const r = bs[p] || {};
    const ta = r.total_assets, tl = r.total_liabilities, te = r.total_stockholder_equity;
    if ([ta, tl, te].every((v) => typeof v === 'number') && ta !== 0) {
      const gapPct = 100 * (ta - (tl + te)) / Math.abs(ta);
      if (Math.abs(gapPct) > Q.identity_gap_pct) {
        add('accounting_identity_gap', 'medium', gapPct, p,
          `assets ${ta.toLocaleString()} vs liabilities+equity ${(tl + te).toLocaleString()}`);
      }
    }
  }

  // 6. cash-flow netIncome vs income-statement netIncome
  for (const p of qPeriods.slice(0, 4)) {
    const a = cf[p] && cf[p].net_income;
    const b = is_[p] && is_[p].net_income;
    if (typeof a === 'number' && typeof b === 'number' && b !== 0) {
      const div = pctDiff(a, b);
      if (div !== null && Math.abs(div) > Q.cf_ni_divergence_pct) {
        add('cashflow_net_income_mismatch', 'medium', div, p,
          `cash flow ${a.toLocaleString()} vs income statement ${b.toLocaleString()}`);
      }
    }
  }

  // 7. COMPONENT RECLASSIFICATION: a line item swings violently while its
  //    parent total barely moves — the same money is being moved between
  //    fields. The total is trustworthy; the components are not.
  for (const spec of COMPONENT_TOTALS) {
    for (let i = 1; i < bPeriods.length; i += 1) {
      const cur = bs[bPeriods[i]] || {}, prev = bs[bPeriods[i - 1]] || {};
      const tNow = cur[spec.total], tPrev = prev[spec.total];
      if (typeof tNow !== 'number' || typeof tPrev !== 'number' || tPrev === 0) continue;
      const tChg = Math.abs(pctDiff(tNow, tPrev));
      if (tChg > Q.total_stable_pct) continue;   // total genuinely moved

      for (const part of spec.parts) {
        const pNow = cur[part], pPrev = prev[part];
        if (typeof pNow !== 'number' || typeof pPrev !== 'number' || pPrev === 0) continue;
        const pChg = pctDiff(pNow, pPrev);
        if (pChg !== null && Math.abs(pChg) > Q.component_swing_pct) {
          add('component_reclassified', 'medium', pChg, bPeriods[i],
            `${part} moved ${pChg.toFixed(0)}% (${pPrev.toLocaleString()} -> ` +
            `${pNow.toLocaleString()}) while ${spec.total} moved ${tChg.toFixed(1)}%. ` +
            `Use ${spec.total} for ${spec.label}, not the components.`);
        }
      }
    }
  }

  // 8. REPEATED VALUE: identical figure in consecutive periods. Real financials
  //    almost never repeat to the dollar; this is a carry-forward.
  for (const [statement, byPeriod] of Object.entries(index)) {
    if (!FLOW_STATEMENTS.has(statement)) continue;
    const ps = Object.keys(byPeriod).sort();
    for (let i = 1; i < ps.length; i += 1) {
      const cur = byPeriod[ps[i]], prev = byPeriod[ps[i - 1]];
      for (const [attr, v] of Object.entries(cur)) {
        if (typeof v !== 'number' || Math.abs(v) < Q.repeated_min_abs) continue;
        if (prev[attr] === v) {
          add('repeated_value', 'low', v, ps[i],
            `${statement}.${attr} identical in ${ps[i - 1]} and ${ps[i]} ` +
            `(${v.toLocaleString()}) — carry-forward, not a real figure`);
        }
      }
    }
  }

  // 9. negative equity
  const latestB = bPeriods.length ? bs[bPeriods[bPeriods.length - 1]] : null;
  if (latestB && typeof latestB.total_stockholder_equity === 'number'
      && latestB.total_stockholder_equity < 0) {
    add('negative_equity', 'medium', latestB.total_stockholder_equity,
      bPeriods[bPeriods.length - 1],
      'P/B and ROE undefined; vendor reports 0, which ranks above genuinely negative values');
  }

  // 10. otherStockholderEquity mirroring totalStockholderEquity
  const mirrored = bPeriods.filter((p) => {
    const r = bs[p] || {};
    return typeof r.other_stockholder_equity === 'number'
        && r.other_stockholder_equity === r.total_stockholder_equity;
  });
  if (mirrored.length && mirrored.length < bPeriods.length) {
    add('other_equity_mirrors_total', 'low', mirrored.length, mirrored[mirrored.length - 1],
      `other_stockholder_equity == total_stockholder_equity in ${mirrored.length}/` +
      `${bPeriods.length} periods but not the rest — field meaning is not stable`);
  }

  // 11. propertyPlantAndEquipment gross == net in some periods only
  const ppeSame = bPeriods.filter((p) => {
    const r = bs[p] || {};
    return typeof r.property_plant_and_equipment_gross === 'number'
        && typeof r.property_plant_and_equipment_net === 'number'
        && r.property_plant_and_equipment_net !== 0
        && Math.abs(r.property_plant_and_equipment_gross - r.property_plant_and_equipment_net)
           / Math.abs(r.property_plant_and_equipment_net) < 0.01;
  });
  const ppeBoth = bPeriods.filter((p) => {
    const r = bs[p] || {};
    return typeof r.property_plant_and_equipment_gross === 'number'
        && typeof r.property_plant_and_equipment_net === 'number';
  });
  if (ppeSame.length && ppeBoth.length && ppeSame.length < ppeBoth.length) {
    add('ppe_gross_equals_net', 'low', ppeSame.length, ppeSame[ppeSame.length - 1],
      `gross == net in ${ppeSame.length}/${ppeBoth.length} periods — the gross field ` +
      `is not consistently gross; do not derive accumulated depreciation from it`);
  }

  return flags;
}

// ---- collect the single payload --------------------------------------------

const inputItems = $input.all();
const payloads = [];
for (const item of inputItems) {
  const json = item.json;
  const list = Array.isArray(json) ? json : [json];
  for (const p of list) if (p && typeof p === 'object') payloads.push({ payload: p, itemJson: json });
}
if (payloads.length === 0) {
  throw new Error(
    'No fundamentals payload received. The HTTP node returned nothing usable — ' +
    'check for a 404 or rate-limit response before this node.'
  );
}

const loopList = loopItems();
const { payload, itemJson } = payloads[0];
const general = readGeneral(payload);
const ticker = resolveTicker(general, payload, itemJson, loopList, payloads.length);

const out = new Map();
const index = {};
const filings = [];
const stats = { nullsDropped: 0, collisions: [], badAttributes: [], badPeriods: [] };

transform(payload, ticker, out, stats, index, filings);

// `out` holds statement facts AND the single market_stats row. Only facts carry
// statement/period_end/attribute, so sort those alone: the comparator
// dereferences all three and throws if it is ever handed the market_stats row
// as its first argument. It survives today only because V8 happens to pass that
// row as `b`, which is luck, not design.
const allOut = [...out.values()];
const factRows = allOut.filter((r) => r.target === 'fact');

const rows = factRows
  .sort(
    (a, b) =>
      a.statement.localeCompare(b.statement) ||
      b.period_end.localeCompare(a.period_end) ||
      a.attribute.localeCompare(b.attribute)
  )
  .concat(allOut.filter((r) => r.target !== 'fact'));

if (factRows.length === 0) {
  throw new Error(
    `${ticker}: payload parsed but produced 0 fact rows. Likely an EODHD error ` +
    `body or an empty record — do not insert a phantom ingest.`
  );
}

// ---- company row ------------------------------------------------------------

const periodsAll = allPeriods(index);
const latestPeriod = periodsAll.length ? periodsAll[periodsAll.length - 1] : null;

const fyMonth = parseFiscalMonth(general.FiscalYearEnd);
const fy = fiscalYearEndDate(fyMonth, latestPeriod);

const companyRow = {
  target: 'company',
  ticker,
  fiscal_year_end_month: fyMonth,             // 12
  fiscal_year_end_day: fy ? fy.day : null,    // 31 (leap-aware for Feb)
  fiscal_year_end_date: fy ? fy.iso : null,   // '2025-12-31'
  fiscal_year_end_raw: cleanCompanyString(
    general.FiscalYearEnd === undefined || general.FiscalYearEnd === null
      ? null : String(general.FiscalYearEnd)),
  latest_period_end: latestPeriod,
  most_recent_quarter: (payload.Highlights && normaliseDate(payload.Highlights.MostRecentQuarter)) || null,
  last_seen: AS_OF,
  run_id: RUN_ID,
  source: SOURCE,
};
const encodingRepaired = [];
for (const [src, col] of Object.entries(COMPANY_FIELDS)) {
  const raw = general[src];
  const cleaned = cleanCompanyString(raw === undefined ? null : raw);
  if (typeof raw === 'string' && typeof cleaned === 'string' && cleaned !== raw.trim()) {
    encodingRepaired.push(`${col}: ${JSON.stringify(raw)} -> ${JSON.stringify(cleaned)}`);
  }
  companyRow[col] = cleaned;
}
if (companyRow.ipo_date) companyRow.ipo_date = normaliseDate(String(companyRow.ipo_date));
if (companyRow.is_delisted !== null && companyRow.is_delisted !== undefined) {
  companyRow.is_delisted = (companyRow.is_delisted === true
    || String(companyRow.is_delisted).toLowerCase() === 'true'
    || String(companyRow.is_delisted) === '1');
}
if (fyMonth === null && general.FiscalYearEnd !== undefined) {
  stats.badAttributes.push(`FiscalYearEnd:${general.FiscalYearEnd}`);
}

// ---- quality flags ----------------------------------------------------------

const flags = qualityFlags(ticker, payload, index, filings);
const earnings = emitEarnings(payload, ticker);   

// Encoding damage arrives in the feed itself, so record how often it happens.
// If this fires across many tickers the fix belongs in the HTTP node's
// response charset, not in per-row repair.
if (encodingRepaired.length) {
  flags.push({
    target: 'quality', ticker, check: 'encoding_repaired', severity: 'low',
    value_num: encodingRepaired.length, period_end: null,
    detail: encodingRepaired.join('; ').slice(0, 500),
    as_of: AS_OF, run_id: RUN_ID, source: SOURCE,
  });
}

// ---- output -----------------------------------------------------------------

if (EMIT_SUMMARY) {
  const bySeverity = (s) => flags.filter((f) => f.severity === s).length;
  return [{
    json: {
      _summary: true,
      ticker,
      sector: companyRow.sector,
      industry: companyRow.industry,
      fact_rows: rows.filter((r) => r.target === 'fact').length,
      market_stats_rows: rows.filter((r) => r.target === 'market_stats').length,
      quality_flags: flags.length,
      flags_high: bySeverity('high'),
      flags_medium: bySeverity('medium'),
      flags_low: bySeverity('low'),
      fiscal_year_end_date: companyRow.fiscal_year_end_date,
      fiscal_year_end_raw: companyRow.fiscal_year_end_raw,
      latest_period_end: latestPeriod,
      nulls_dropped: stats.nullsDropped,
      // JSON strings, not arrays — n8n/jsonb top-level array convention
      flag_names: JSON.stringify(flags.map((f) => `${f.severity}:${f.check}${f.period_end ? '@' + f.period_end : ''}`)),
      collision_keys: JSON.stringify(stats.collisions.slice(0, 25)),
      bad_attributes: JSON.stringify(stats.badAttributes.slice(0, 25)),
      bad_periods: JSON.stringify(stats.badPeriods.slice(0, 25)),
      loop_items: loopList === null ? 'unreachable' : String(loopList.length),
      run_id: RUN_ID,
      as_of: AS_OF,
    },
  }];
}

return [companyRow, ...flags, ...earnings, ...rows].map((r) => ({ json: r }));
